<?php
if ( ! defined( 'ABSPATH' ) || ! class_exists( 'Estandar_Integration_Provider' ) ) { return; }

/** Optional Core UI adapter; credentials remain owned by this integration. */
final class Estandar_Search_Console_Integration_Provider extends Estandar_Integration_Provider {
    public function id(): string { return 'google_search_console'; }
    public function label(): string { return 'Google Search Console'; }
    public function description(): string { return 'Sincroniza métricas orgánicas históricas por landing y query. No modifica Leads.'; }
    public function get_settings(): array { return array_merge( array( 'site_url' => '', 'client_id' => '', 'client_secret' => '', 'refresh_token' => '' ), (array) get_option( 'estandar_seo_search_console', array() ) ); }
    public function settings_fields(): array { $s = $this->get_settings(); $properties = ( new Estandar_Search_Console_Adapter() )->properties(); $property_field = array( 'name' => 'seo_search_console_site_url', 'label' => 'Search Console property', 'type' => 'text', 'value' => $s['site_url'], 'placeholder' => 'https://example.com/', 'description' => 'Guarda primero OAuth y luego selecciona una propiedad autorizada.' ); if ( ! empty( $properties['success'] ) ) { $options = array(); foreach ( $properties['properties'] as $property ) { $options[ $property['url'] ] = $property['url'] . ' (' . $property['permission'] . ')'; } if ( $s['site_url'] !== '' && ! isset( $options[ $s['site_url'] ] ) ) { $options[ $s['site_url'] ] = $s['site_url'] . ' (no autorizada)'; } $property_field = array_merge( $property_field, array( 'type' => 'select', 'options' => $options ) ); } return array(
        array( 'name' => 'seo_enabled', 'label' => 'Activar SEO Intelligence', 'type' => 'checkbox', 'checked' => Estandar_SEO_Service::enabled(), 'checkbox_label' => 'Permitir cron, sincronización manual y backfill.' ),
        $property_field,
        array( 'name' => 'seo_commercial_timezone', 'label' => 'Zona comercial IANA', 'type' => 'text', 'value' => get_option( 'estandar_seo_commercial_timezone', 'America/Santiago' ), 'placeholder' => 'America/Santiago', 'description' => 'Determina la fecha comercial consultada a Search Console; los timestamps técnicos permanecen en UTC.' ),
        array( 'name' => 'seo_stability_delay_days', 'label' => 'Demora de estabilidad (días)', 'type' => 'text', 'value' => Estandar_SEO_Service::stability_delay_days(), 'placeholder' => '3', 'description' => 'Entre 1 y 30 días calendario comerciales antes de consultar Search Console.' ),
        array( 'name' => 'seo_search_console_client_id', 'label' => 'OAuth Client ID', 'type' => 'text', 'value' => $s['client_id'] ),
        array( 'name' => 'seo_search_console_client_secret', 'label' => 'OAuth Client Secret', 'type' => 'password', 'value' => '', 'placeholder' => $s['client_secret'] !== '' ? '•••••••• (secreto guardado)' : '' ),
        array( 'name' => 'seo_search_console_refresh_token', 'label' => 'Refresh Token', 'type' => 'password', 'value' => '', 'placeholder' => $s['refresh_token'] !== '' ? '•••••••• (token guardado)' : '' ),
    ); }
    public function save_settings( array $post ): void { $old = $this->get_settings(); $site = trim( (string) ( $post['seo_search_console_site_url'] ?? '' ) ); $next = array( 'site_url' => $site, 'client_id' => trim( (string) ( $post['seo_search_console_client_id'] ?? '' ) ), 'client_secret' => trim( (string) ( $post['seo_search_console_client_secret'] ?? '' ) ) ?: $old['client_secret'], 'refresh_token' => trim( (string) ( $post['seo_search_console_refresh_token'] ?? '' ) ) ?: $old['refresh_token'] ); $timezone = trim( (string) ( $post['seo_commercial_timezone'] ?? 'America/Santiago' ) ); try { new DateTimeZone( $timezone ); } catch ( Exception $e ) { $timezone = 'America/Santiago'; } update_option( 'estandar_seo_enabled', isset( $post['seo_enabled'] ) ? '1' : '0', false ); update_option( 'estandar_seo_commercial_timezone', $timezone, false ); update_option( 'estandar_seo_stability_delay_days', max( 1, min( 30, absint( $post['seo_stability_delay_days'] ?? 3 ) ) ), false ); update_option( 'estandar_seo_search_console', $next, false ); delete_transient( 'estandar_seo_search_console_token' ); }
    public function status(): array { $c = $this->get_settings(); $configured = $c['site_url'] !== '' && $c['client_id'] !== '' && $c['client_secret'] !== '' && $c['refresh_token'] !== ''; return array( 'configured' => $configured, 'active' => $configured && Estandar_SEO_Service::enabled(), 'summary' => $configured ? ( Estandar_SEO_Service::enabled() ? 'Activa · ' : 'Configurada, deshabilitada · ' ) . Estandar_SEO_Service::commercial_timezone()->getName() . ' · demora ' . Estandar_SEO_Service::stability_delay_days() . ' días.' : 'OAuth y propiedad Search Console pendientes.' ); }
    public function render_extra(): void { if ( class_exists( 'Estandar_SEO_Operations' ) ) { Estandar_SEO_Operations::render_panel(); } }
}
